function readRoute(){const parts=window.location.hash.replace(/^#\/?/,'').split('/').filter(Boolean);if(parts[0]==='discover'||parts[0]==='messages')return{section:parts[0],serverId:'',channelId:''};if(parts[0]==='servers')return{section:'servers',serverId:parts[1]||'',channelId:parts[2]==='channels'?parts[3]||'':''};return{section:'servers',serverId:'',channelId:''}}
const initialRoute=readRoute()
const initial=(s:string)=>s.slice(0,1).toUpperCase()
function Avatar({name,color='gold',src}:{name:string;color?:string;src?:string}){return <div className={'avatar avatar-'+color}>{src?<img src={src} alt={name}/>:initial(name)}</div>}

