 {mode==='register'?<><label>Username<div className="field"><AtSign size={16}/><input value={username} onChange={e=>setUsername(e.target.value)} placeholder="yourname" minLength={3} maxLength={32} pattern="[A-Za-z0-9_]+" required/></div></label><label>Display name <span className="optional">OPTIONAL</span><div className="field"><Users size={16}/><input value={displayName} onChange={e=>setDisplayName(e.target.value)} placeholder="How people know you" maxLength={64}/></div></label><label>Email address<div className="field"><Mail size={16}/><input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" required/></div></label></>:<label>Username or email<div className="field"><AtSign size={16}/><input value={identifier} onChange={e=>setIdentifier(e.target.value)} placeholder="name#4821 or you@example.com" required/></div></label>}
